import {applies,traits} from './taxonomy.js';
export const TAGS={build:'流派搭配',strategy:'策略選擇',action:'即時操作',complex:'系統複雜',random:'隨機變化',manage:'建設經營',turn:'回合推進',cards:'卡牌玩法',loot:'裝備掉落',grind:'重複養成',social:'多人互動',style:'視覺風格',story:'故事敘事',explore:'探索'};
export const REASONS={build:['喜歡研究流派','build',1],strategy:['策略選擇有趣','strategy',1],randomGood:['隨機變化有樂趣','random',1],style:['喜歡美術與世界','style',1],story:['故事吸引我','story',1],social:['與朋友玩很開心','social',1],actionGood:['享受即時操作','action',1],complexBad:['系統難以理解','complex',-1],actionBad:['太依賴即時反應','action',-1],combo:['複雜系統＋即時反應負擔太高','complexAction',-1],randomBad:['運氣不好時難以補救','randomRisk',-1],grindBad:['重複養成／終局單調','grind',-1],manageBad:['建設經營不合胃口','manage',-1],pace:['步調與操作風格不合',null,0],styleBad:['題材或風格不合',null,0],other:['其他／說不上來',null,0]};
