export function normalize(data){const raw=Array.isArray(data)?data:data?.response?.games;if(!Array.isArray(raw)||!raw.length)throw Error('找不到遊戲清單。請匯入含 response.games 的 Steam JSON。');const seen=new Set();return raw.map(g=>{const id=Number(g.appid),m=g.minutes??g.playtime_forever;if(!Number.isSafeInteger(id)||id<=0||typeof g.name!=='string'||!g.name.trim()||!Number.isFinite(m)||m<0)throw Error('遊戲資料缺少有效的 AppID、名稱或時數。');if(seen.has(id))throw Error('資料有重複的 AppID，請重新匯出。');seen.add(id);return {appid:id,name:g.name,minutes:m};});}
