export function isIdle(g){return /idle|clicker|Task Bar Hero|Banana|Mr\.Mine/i.test(g.name);}
export function profile(answers,catalog){const weights={},evidence={};const add=(t,v,g)=>{weights[t]=(weights[t]||0)+v;(evidence[t]??=[]).push(g.name);};for(const [id,a] of Object.entries(answers)){const g=catalog.find(g=>g.appid===Number(id));if(!g||a.rating==='skip')continue;const reasons=a.reasons||[];for(const k of reasons){const r=REASONS[k];if(r?.[1]&&(a.taxonomyVersion>=3||applies(k,g,a.rating))&&!['complexBad','combo'].includes(k)){let t=r[1];if(k==='build')t=traits(g).includes('tuning')?'tuning':traits(g).includes('cards')?'cards':'build';add(t,r[2]*2,g);}}if(a.rating==='like'&&!reasons.length)for(const t of traits(g))add(t,.25,g);
