import assert from 'node:assert/strict';
const require=createRequire(import.meta.url),catalog=require('./public/catalog.json');
const find=n=>catalog.find(g=>g.name===n);
const positive=['Slay the Spire','Brotato'].map(find);assert.ok(positive.every(Boolean));
const noita=find('Noita');assert.ok(noita);
const before=Object.fromEntries(positive.map(g=>[g.appid,{rating:'like',reasons:[],taxonomyVersion:3}]));
const after={...before,[noita.appid]:{rating:'regret',reasons:[],taxonomyVersion:3}};
const a=signals(before,catalog),b=signals(after,catalog);assert.deepEqual(a.weights,b.weights);
assert.deepEqual(profile(before,catalog).weights,profile(after,catalog).weights);
const candidate={appid:999999001,name:'Synthetic shared-tag candidate',tagIds:[32322,4231,19]};
const pa=makePlan(before,[],6,{},catalog),pb=makePlan(after,[],6,{},catalog);
const ra=assess(candidate,pa,before),rb=assess(candidate,pb,after);assert.deepEqual(ra,rb);
const reviews=[{total_reviews:19,total_positive:19},{total_reviews:20,total_positive:4},{total_reviews:20,total_positive:3},{total_reviews:20}].map(input=>({input,actualV14:evaluateReviews(input)}));
writeFileSync('./persona-probe-output.json',JSON.stringify({provenance:'Synthetic test inputs using tracked provisional catalog; not a real player snapshot. No playtimes invented.',before,after,candidate,outputs:{before:a.weights,after:b.weights,candidateBefore:ra,candidateAfter:rb},reviews,findings:['Noita bare regret already preserves mechanic weights and this candidate assessment.','V14 accepts 3/20 positives and missing positive count: new 20% gate still required.','Other attributable feedback paths require separate review; this probe does not establish universal invariance.']},null,2));
console.log('Persona minimal probe: PASS (profile, signals, candidate assessment).');
